	'messages:apierror-baddiff' => 'en:The diff cannot be retrieved. One or both revisions do not exist or you do not have permission to view them.',
	'messages:apierror-baddiffto' => 'en:<var>$1diffto</var> must be set to a non-negative number, <kbd>prev</kbd>, <kbd>next</kbd> or <kbd>cur</kbd>.',
	'messages:apierror-badformat-generic' => 'en:The requested format $1 is not supported for content model $2.',
